test('validates list_sessions paging fields and drops client-supplied identity', () => {
  const before = {sessionId: 'session-1', updatedAt: '2026-01-15T14:30:00.000Z'};
  const invalidLimits = [-1, 1.5, '2'];
  const invalidCursors = [
    {sessionId: '', updatedAt: before.updatedAt},
    {sessionId: 'x'.repeat(129), updatedAt: before.updatedAt},
    {sessionId: 'session-1', updatedAt: 'not a date'},
  ];

  expect({
    bare: validateMessage({type: 'list_sessions'}),
    withFields: validateMessage({type: 'list_sessions', limit: 0, before, userId: 'other-user'}),
    invalidLimits: invalidLimits.map(limit => validateMessage({type: 'list_sessions', limit})),
    invalidCursors: invalidCursors.map(before => validateMessage({type: 'list_sessions', before})),
  }).toEqual({
    bare: {valid: true, data: {type: 'list_sessions'}},
    withFields: {valid: true, data: {type: 'list_sessions', limit: 0, before}},
    invalidLimits: invalidLimits.map(() => ({valid: false, error: expect.stringContaining('limit')})),
    invalidCursors: invalidCursors.map(() => ({valid: false, error: expect.stringContaining('before')})),
  });
});

